 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-length uniform nonzero lines are the partition separators.
    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    def spans(n, seps):
        out, start = [], 0
        for x in seps:
            if start < x:
                out.append((start, x))
            start = x + 1
        if start < n:
            out.append((start, n))
        return out
    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    # Copy the populated tile into every tile slot, preserving separator lines.
    score = lambda a, b: sum(grid[r][c] != 0 for r in range(a[0], a[1]) for c in b[0:1] for c in range(b[0], b[1]))
    src = max(((ri, ci) for ri in range(len(rs)) for ci in range(len(cs))),
              key=lambda k: score(rs[k[0]], cs[k[1]]))
    sr, sc = rs[src[0]], cs[src[1]]
    out = [row[:] for row in grid]
    for ri, rr in enumerate(rs):
        for ci, cc in enumerate(cs):
            if ri == src[0] and ci == src[1]:
                continue
            for r in range(rr[0], rr[1]):
                for c in range(cc[0], cc[1]):
                    # Map corresponding tile positions; copy only non-background marks.
                    sr0 = sr[0] + (r - rr[0]) % (sr[1] - sr[0])
                    sc0 = sc[0] + (c - cc[0]) % (sc[1] - sc[0])
                    if grid[sr0][sc0] != 0:
                        out[r][c] = grid[sr0][sc0]
    return out
